void TIM1_PA8_PWM_Init(void)
{
    /* 1. Enable peripheral clocks for GPIOA and TIM1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 in Alternate Function mode (AF6 -> TIM1_CH1) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE8_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos); /* AF mode (10b) */

    GPIOA->AFR[1] &= ~(GPIO_AFRH_AFSEL8_Msk);
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos); /* AF6 */

    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos); /* High speed */
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk); /* No pull-up/pull-down */

    /* 3. Configure TIM1 for 20 kHz PWM, 25% duty cycle */
    /* f_tim = 170 MHz. Target = 20 kHz -> Counter period = 170,000,000 / 20,000 = 8500 cycles */
    TIM1->PSC = 0;              /* Prescaler = 0 -> timer tick = 170 MHz */
    TIM1->ARR = 8500 - 1;       /* ARR = 8499 -> Period = 8500 ticks = 50 us (20 kHz) */
    TIM1->CCR1 = 2125;          /* CCR1 = 2125 -> Duty = 2125 / 8500 = 25% */

    /* Configure PWM mode 1 on CH1, enable output preload */
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE; /* PWM mode 1 (0110b) */

    /* Enable CH1 output */
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Enable ARR preload */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Advanced timer TIM1: Main Output Enable (MOE) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Force update event to load preload registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* Enable counter */
    TIM1->CR1 |= TIM_CR1_CEN;
}

