    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Tạo Update Event để nạp ngay giá trị từ preload registers vào active registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* Kích hoạt bộ đếm TIM1 */
    TIM1->CR1 |= TIM_CR1_CEN;
}

